SELECT session_id, event_type, page_values, add_to_cart_count FROM (SELECT session_id, event_type, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END) AS add_to_cart_count FROM web_events WHERE event_time >= '2024-04-05' GROUP BY session_id, event_type) AS sub WHERE add_to_cart_count < 53 ORDER BY event_type, add_to_cart_count, session_id LIMIT 5
